export function buildStencilPath(
  stencilId               ,
  width        ,
  height        ,
  flipH          = false
)                                               {
  if (!stencilId || !STENCILS[stencilId]) {
    return {
      d: `M 0 0 L ${width} 0 L ${width} ${height} L 0 ${height} Z`,
      mode: "fillstroke",
    };
  }
  const stencil = STENCILS[stencilId];
  const sx = width / 100;
  const sy = height / 100;
  const tx = (x        )         => Number(((flipH ? 100 - x : x) * sx).toFixed(2));
  const ty = (y        )         => Number((y * sy).toFixed(2));

  const parts           = [];
  for (const cmd of stencil.cmds) {
    if (cmd.t === "M") {
      parts.push(`M ${tx(cmd.x)} ${ty(cmd.y)}`);
    } else if (cmd.t === "L") {
      parts.push(`L ${tx(cmd.x)} ${ty(cmd.y)}`);
    } else if (cmd.t === "C") {
      parts.push(
        `C ${tx(cmd.x1)} ${ty(cmd.y1)}, ${tx(cmd.x2)} ${ty(cmd.y2)}, ${tx(cmd.x3)} ${ty(cmd.y3)}`
      );
    } else if (cmd.t === "A") {
      const rx = Number((cmd.rx * sx).toFixed(2));
      const ry = Number((cmd.ry * sy).toFixed(2));
      const sweep = flipH ? (cmd.sweep ? 0 : 1) : cmd.sweep;
      parts.push(`A ${rx} ${ry} ${cmd.rot} ${cmd.large} ${sweep} ${tx(cmd.x)} ${ty(cmd.y)}`);
    }
  }
  return { d: parts.join(" "), mode: stencil.mode };
}
